    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>& edges) {
        int n = nums.size();
        vector<int> ans(n, -1);
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<vector<int>> coprimes(51);
        for (int i = 1; i <= 50; ++i) {
            for (int j = 1; j <= 50; ++j) {
                if (std::gcd(i, j) == 1) coprimes[i].push_back(j);
            }
        }
        vector<vector<pair<int, int>>> last(51);
        auto dfs = [&](auto&& self, int u, int p, int d) -> void {
            int val = nums[u];
            int best_d = -1, best_node = -1;
            for (int v : coprimes[val]) {
                if (!last[v].empty()) {
                    auto [dd, nd] = last[v].back();
                    if (dd > best_d) {
                        best_d = dd;
                        best_node = nd;
                    }
                }
            }
            ans[u] = best_node;
            last[val].push_back({d, u});
            for (int v : adj[u]) {
                if (v != p) self(self, v, u, d + 1);
            }
            last[val].pop_back();
        };
        dfs(dfs, 0, -1, 0);
        return ans;
    }
};
