        }
 vector<vector<int>> dirs = {{0,1},{1,0},{0,-1},{-1,0}};
        auto valid = [&](int i, int j) {
            return i >= 0 && i < m && j >= 0 && j < n;
        };
        auto find = [&](auto& self, vector<int>& p, int x) -> int {
            return p[x] == x ? x : p[x] = self(self, p, p[x]);
        };
        auto unite = [&](vector<int>& p, int x, int y) {
            int px = find(find, p, x ), py = find(find, p, y);
            if (px != py) p[px] = py;
        };
        int N = m * n + 1;
        vector<int> p(N);
        for (int i = 0; i < N; i++) p[i] = i ;
        int dummy = m * n;
        for (int i = 0; i < m; i++) {
