class Solution {
public:
    int largestMagicSquare(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<long long>> rowPref(m, vector<long long>(n + 1, 0));
        vector<vector<long long>> colPref(n, vector<long long>(m + 1, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
                colPref[j][i + 1] = colPref[j][i] + grid[i][j];
            }
        }
        auto isMagic = [&](int r, int c, int k) -> bool {
            long long S = rowPref[r][c + k] - rowPref[r][c];
            for (int i = r; i < r + k; ++i) {
                if (rowPref[i][c + k] - rowPref[i][c] != S) return false;
            }
            for (int j = c; j < c + k; ++j) {
                if (colPref[j][r + k] - colPref[j][r] != S) return false;
            }
            long long d1 = 0, d2 = 0;
            for (int t = 0; t < k; ++t) {
                d1 += grid[r + t][c + t];
                d2 += grid[r + t][c + k - 1 - t];
            }
            return d1 == S && d2 == S;
        };
        int maxK = min(m, n);
        for (int k = maxK; k >= 1; --k) {
            for (int i = 0; i + k <= m; ++i) {
                for (int j = 0; j + k <= n; ++j) {
                    if (isMagic(i, j, k)) return k;
                }
            }
        }
        return 1;
    }
};
