class Solution {
public:
    int numOfWays(vector<int>& nums) {
        const int MOD = 1000000007;
        int n = nums.size();
        vector<vector<long long>> C(n + 1, vector<long long>(n + 1, 0));
        for (int i = 0; i <= n; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }
        function<long long(const vector<int>&)> dfs = [&](const vector<int>& arr) -> long long {
            int m = arr.size();
            if (m <= 2) return 1;
            vector<int> left, right;
            for (int i = 1; i < m; ++i) {
                if (arr[i] < arr[0]) left.push_back(arr[i]);
                else right.push_back(arr[i]);
            }
            long long ways = C[left.size() + right.size()][left.size()];
            ways = ways * dfs(left) % MOD;
            ways = ways * dfs(right) % MOD;
            return ways;
        };
        long long total = dfs(nums);
        return (total - 1 + MOD) % MOD;
    }
};
