class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int n = nums.size();
        int sum = 0;
        for (int num : nums) sum += num;
        if (sum % k != 0) return false;
        int target = sum / k;
        sort(nums.rbegin(), nums.rend());
        if (nums[0] > target) return false;
        vector<bool> used(n, false);
        return dfs(nums, used, 0, k, 0, target);
    }
private:
    bool dfs(vector <int>& nums, vector<bool>& used, int start, int k, int currSum, int target) {
        if (k == 0) return true;
        if (currSum == target) {
            return dfs(nums, used, 0, k - 1, 0, target);
 }
        for (int i = start; i < nums.size(); ++i) {
            if (used[i] || currSum + nums[i] > target) continue;
            used[i] = true;
            if (dfs(nums, used, i + 1, k, currSum + nums[i], target)) return true;
            used[i] = false;
            if (currSum == 0) return false;
            while (i + 1 < nums.size() && nums[i + 1] == nums[i]) ++i;
        }
        return false;
    }
};
```     The backtracking approach works well here because n<=16 and the frequency constraint keeps branching manageable. Sorting descending and the pruning when currSum==0 after trying a starting number ensure we don't waste time on impossible branches. The used array tracks which numbers we've assigned, and the recursive call restarts the search for the next subset from index 0 when a subset is complete. This correctly handles the example where subsets like (5), (1,4), (2,3), (2,3) are found in some order. For the second example, the sum not being divisible by 3 immediately returns false.

