class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        vector<string> res;
        unordered_set<string> seen;
        queue<pair<string, int>> q;
        q.push({s, 0});
        seen.insert(s);
        bool found = false;
        while (!q.empty()) {
            auto [str, level] = q.front(); q.pop();
            if (isValid(str)) {
                res.push_back(str);
                found = true;
                continue;
            }
            if (found) continue;
            for (int i = 0; i < str.size(); i++) {
                if (str[i] != '(' && str[i] != ')') continue;
                string next = str.substr(0, i) + str.substr(i + 1);
                if (seen.find(next) != seen.end()) continue;
                seen.insert(next);
                q.push({next, level 1});
            }
        }
        return res;
    }
private:
    bool isValid(const string& str) {
        int cnt = 0;
        for (char c : str) {
            if (c == '(') cnt++;
            else if (c == ')') {
                if (cnt ==  0) return false;
                cnt--;
            }
        }
        return cnt == 0;
    }
};
```     This BFS approach removes one parenthesis at a time, level by level, ensuring we find the minimum removals first. We use a queue and a set to track visited states and avoid duplicates. When we encounter a valid string at the current level, we collect it and stop further processing since any deeper levels would require more removals. The isValid helper checks balance without negative counts. This works efficiently given the constraints (n ≤ 25, ≤20 parentheses).

