class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int leftRem = 0, rightRem = 0;
        for (char c : s) {
            if (c == '(') {
                leftRem++;
            } else if (c == ')') {
                if (leftRem > 0) leftRem--;
                else rightRem++;
            }
        }
        unordered_set<string> resSet;
        string path;
        dfs(s, 0, leftRem, rightRem, 0, path, resSet);
        return vector<string>(resSet.begin(), resSet.end());
    }

private:
    void dfs(const string& s, int i, int leftRem, int rightRem, int open, string& path, unordered_set<string>& resSet) {
        if (i == s.length()) {
            if (leftRem == 0 && rightRem == 0 && open == 0) {
                resSet.insert(path);
            }
            return;
        }
        char c = s[i];
        if (c != '(' && c != ')') {
            path.push_back(c);
            dfs(s, i + 1, leftRem, rightRem, open, path, resSet);
            path.pop_back();
            return;
        }
        if (c == '(' && leftRem > 0) {
            dfs(s, i + 1, leftRem - 1, rightRem, open, path, resSet);
        } else if (c == ')' && rightRem > 0) {
            dfs(s, i + 1, leftRem, rightRem - 1, open, path, resSet);
        }
        if (c == '(') {
            path.push_back(c);
            dfs(s, i + 1, leftRem, rightRem, open + 1, path, resSet);
            path.pop_back();
        } else if (c == ')' && open > 0) {
            path.push_back(c);
            dfs(s, i + 1, leftRem, rightRem, open - 1, path, resSet);
            path.pop_back();
        }
    }
};
```

