class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        int m = stickers.size();
        vector<int> mask(m);
        for (int i = 0; i < m; ++i) {
            int mk = 0;
            for (char c : stickers[i]) {
                for (int j = 0; j < n; ++j) {
                    if (c == target[j]) {
                        mk |= (1 << j);
                        break;
                    }
                }
            }
            mask[i] = mk;
        }
 const int INF = 1e9;
        vector<int> dp(1 << n, INF);
        dp[0] = 0;
        for (int maskk = 0; maskk < (1 << n); ++maskk) {
            if (dp[maskk] == INF) continue ;
            for (int i = 0; i < m; ++i) {
                int newmask = maskk | mask[i];
                if (newmask != maskk) {
                    dp[newmask] = min(dp[newmask], dp[maskk] + 1);
                }
            }
        }
 int ans = dp[(1 << n) - 1];
        return ans == INF ? -1 : ans;
    }
};
